<?php

declare(strict_types=1);

namespace LaravelNecromancer\Benchmark;

final class TaskSuiteWriter
{
    /** @param array<int, array<string, mixed>> $tasks */
    public function render(array $tasks, string $generatedAt = ''): string
    {
        $date = $generatedAt ?: date('Y-m-d');
        $body = $this->renderTasks($tasks);

        return <<<PHP
        <?php

        // Benchmark task suite grounded to this application.
        // Generated by `php artisan necromancer:benchmark --generate-suite` on {$date}.
        // Re-run after `necromancer:scan` to keep assertions in sync with the manifest.
        return [
        {$body}
        ];
        PHP;
    }

    /** @param array<int, array<string, mixed>> $tasks */
    private function renderTasks(array $tasks): string
    {
        return implode("\n\n", array_map(
            fn (array $task): string => $this->renderTask($task),
            $tasks
        ));
    }

    /** @param array<string, mixed> $task */
    private function renderTask(array $task): string
    {
        $id = $this->str((string) $task['id']);
        $type = $this->str((string) $task['type']);
        $prompt = $this->str((string) $task['prompt']);
        $requiredKey = isset($task['required_key']) ? $this->str((string) $task['required_key']) : 'null';
        $assertions = $this->renderAssertions((array) ($task['assertions'] ?? []));

        $conditionsLine = '';
        if (isset($task['conditions']) && is_array($task['conditions'])) {
            $items = implode(', ', array_map(fn (string $v): string => $this->str($v), $task['conditions']));
            $conditionsLine = "\n        'conditions'   => [{$items}],";
        }

        return <<<PHP
            [
                'id'           => {$id},
                'type'         => {$type},
                'prompt'       => {$prompt},
                'required_key' => {$requiredKey},{$conditionsLine}
                'assertions'   => [{$assertions}
                ],
            ],
        PHP;
    }

    /** @param array<string, mixed> $assertions */
    private function renderAssertions(array $assertions): string
    {
        $lines = [];

        foreach ($assertions as $key => $value) {
            if ($value === null) {
                continue;
            }
            if (is_array($value)) {
                $items = implode(', ', array_map(fn ($v): string => $this->str((string) $v), $value));
                $lines[] = "        '{$key}' => [{$items}],";
            } else {
                $lines[] = "        '{$key}' => {$this->str((string) $value)},";
            }
        }

        return $lines !== [] ? "\n".implode("\n", $lines)."\n    " : '';
    }

    private function str(string $value): string
    {
        return "'".addcslashes($value, "'\\")."'";
    }
}
